import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  // --- Constants ---
  const PLANE_WIDTH = 1.5;
  const PLANE_HEIGHT = 0.5;
  const TEXT_Z_OFFSET = 0.001; // avoid z-fighting

  // --- Background plane ---
  const bgTex = ctx.textureLoader.load(config.assets.imageUrl);
  bgTex.colorSpace = THREE.SRGBColorSpace;

  const bgMat = new MeshBasicNodeMaterial({
    map: bgTex,
    toneMapped: false, // maintain raw color appearance
  });
  const bgGeom = new THREE.PlaneGeometry(PLANE_WIDTH, PLANE_HEIGHT);
  const bgMesh = new THREE.Mesh(bgGeom, bgMat);

  // --- Text mesh ---
  // textContent is an array; find the "headline" style item
  const textItem = config.textContent?.find(t => t.style === 'headline') || config.textContent?.[0];
  const textStr = textItem?.content || '';
  const textSize = 0.34; // headline scene unit height (from token typography)
  const textOptions = {
    size: textSize,
    weight: textItem?.weight || 400,
    font: 'Lora', // serif display font
    anchor: { x: 0.5, y: 0.5 }, // center
  };
  const textMesh = ctx.fontAtlas.createMesh(textStr, textOptions);
  textMesh.position.z = TEXT_Z_OFFSET;

  // --- Group ---
  const group = new THREE.Group();
  group.add(bgMesh);
  group.add(textMesh);

  // Apply scene placement
  const sp = config.scenePosition;
  group.position.set(sp.position.x, sp.position.y, sp.position.z);
  group.rotation.set(sp.rotation.x, sp.rotation.y, sp.rotation.z);
  group.scale.set(sp.scale.x, sp.scale.y, sp.scale.z);

  // --- Handlers (none) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    bgGeom.dispose();
    bgMat.dispose();
    bgTex.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
    // textMesh from fontAtlas may have internal resources – dispose its children if any
    textMesh.traverse(child => {
      if (child.isMesh) {
        child.geometry?.dispose();
        child.material?.dispose();
      }
    });
  };

  return group;
}
